"""Example usage of Base64ImageConverter utility."""

from phone_agent.utils import Base64ImageConverter, save_base64_as_image, base64_to_image


def example_basic_usage():
    """Basic usage example: convert base64 to image and save."""
    # Example base64 string (this is a minimal example)
    base64_string = ""
    
    # Save base64 string as image
    output_path = "output/example.png"
    saved_path = save_base64_as_image(base64_string, output_path)
    print(f"Image saved to: {saved_path}")


def example_with_converter_class():
    """Example using the Base64ImageConverter class."""
    # Example base64 string
    base64_string = "iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mP8/5+hHgAHggJ/PchI7wAAAABJRU5ErkJggg=="
    
    # Convert base64 to PIL Image
    image = base64_to_image(base64_string)
    print(f"Image size: {image.size}")
    
    # Save with custom format and quality
    output_path = "output/example.jpg"
    saved_path = Base64ImageConverter.save_base64_as_image(
        base64_string, 
        output_path, 
        format="JPEG", 
        quality=85
    )
    print(f"JPEG image saved to: {saved_path}")


def example_with_resize():
    """Example with image resizing."""
    # Example base64 string (in real usage, this would be a full image)
    base64_string = "iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mP8/5+hHgAHggJ/PchI7wAAAABJRU5ErkJggg=="
    
    # Save with resizing
    output_path = "output/resized_example.png"
    saved_path = Base64ImageConverter.save_base64_as_resized_image(
        base64_string,
        output_path,
        max_width=800,
        max_height=600,
        maintain_aspect_ratio=True
    )
    print(f"Resized image saved to: {saved_path}")


def example_load_and_convert():
    """Example: load existing image and convert to base64."""
    # Load an existing image and convert to base64
    try:
        base64_data = Base64ImageConverter.load_image_as_base64("input/example.png")
        print(f"Base64 length: {len(base64_data)}")
        
        # Save it back to verify
        output_path = "output/converted_example.png"
        saved_path = save_base64_as_image(base64_data, output_path)
        print(f"Converted image saved to: {saved_path}")
    except FileNotFoundError:
        print("Input image not found, skipping this example.")


if __name__ == "__main__":
    print("Base64ImageConverter Examples\n")
    
    print("1. Basic Usage:")
    example_basic_usage()
    
